package app.streamnest;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class TrailersTest {
 @Test public void youtubeLinksAreStrictAndCanonical(){String id="xEQP4VVuyrY";for(String s:new String[]{id,"https://youtu.be/"+id,"https://www.youtube.com/watch?v="+id+"&t=2","https://youtube.com/embed/"+id})assertEquals("https://www.youtube.com/watch?v="+id,Trailers.url(s));for(String s:new String[]{"javascript:alert(1)","https://youtube.com.evil/watch?v="+id,"https://user@youtube.com/watch?v="+id,"https://evil.example/"+id})assertEquals("",Trailers.url(s));}
 @Test public void exactIdentityAndAvailabilityFallbackAreRequired()throws Exception{Trailers.Fetcher original=Trailers.fetcher;try{synchronized(Trailers.cache){Trailers.cache.clear();}int[] calls={0};Trailers.fetcher=(url,deadline)->{calls[0]++;if(url.contains("cinemeta"))return new JSONObject("{meta:{id:'tt1',trailers:[{type:'Trailer',source:'aaaaaaaaaaa'},{type:'Trailer',source:'xEQP4VVuyrY'}]}}");if(url.contains("aaaaaaaaaaa"))throw new java.io.IOException("404");return new JSONObject().put("provider_name","YouTube").put("title","Trailer");};Catalog.Title t=Catalog.parse(new JSONObject().put("imdb","tt1").put("title","Fixture"),"shows");assertEquals("xEQP4VVuyrY",Trailers.resolve(t).id);assertEquals(3,calls[0]);Trailers.resolve(t);assertEquals(3,calls[0]);assertTrue(Trailers.candidates(new JSONObject().put("id","tt2"),"tt1").isEmpty());assertTrue(Trailers.candidates(null,"tt1").isEmpty());}finally{Trailers.fetcher=original;Trailers.cache.clear();}}
}
